        # For each combo, consider all permutations
        for perm in itertools.permutations(combo):
            # Build the edge set for this cycle
            cycle_edges = []
            for k in range(L):
                u, v = perm[k], perm[(k+1) % L]
                if u > v:
                    u, v = v, u
                cycle_edges.append((u, v))
            # Sort the edges for canonical representation
            cycle_edges = tuple(sorted(cycle_edges))
            all_cycle_edge_sets.add(cycle_edges)

